import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { DatabaseSync } from 'node:sqlite';

export function openProjectStore(databasePath) {
  mkdirSync(dirname(databasePath), { recursive: true });
  const database = new DatabaseSync(databasePath);
  database.exec('PRAGMA foreign_keys = ON');
  database.exec(`
    CREATE TABLE IF NOT EXISTS projects (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL CHECK (length(trim(name)) > 0)
    );
    CREATE TABLE IF NOT EXISTS tasks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      project_id INTEGER NOT NULL REFERENCES projects(id),
      title TEXT NOT NULL CHECK (length(trim(title)) > 0),
      completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
    );
    CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id, id);
  `);
  const list = database.prepare('SELECT id, name FROM projects ORDER BY id ASC');
  const find = database.prepare('SELECT id, name FROM projects WHERE id = ?');
  const insert = database.prepare('INSERT INTO projects (name) VALUES (?)');
  const listTasks = database.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? ORDER BY id ASC');
  const insertTask = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
  const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');

  return {
    list: () => list.all(),
    find: (id) => find.get(id),
    create(name) {
      const trimmedName = name.trim();
      if (!trimmedName) throw new Error('Project name is required');
      return Number(insert.run(trimmedName).lastInsertRowid);
    },
    listTasks(projectId, filter = 'all') {
      return listTasks.all(projectId).filter((task) =>
        filter === 'open' ? !task.completed : filter === 'completed' ? task.completed : true);
    },
    createTask(projectId, title) {
      const trimmedTitle = title.trim();
      if (!trimmedTitle) throw new Error('Task title is required');
      return Number(insertTask.run(projectId, trimmedTitle).lastInsertRowid);
    },
    setTaskCompleted(projectId, taskId, completed) {
      return updateTask.run(completed ? 1 : 0, projectId, taskId).changes > 0;
    },
    close: () => database.close(),
  };
}
import { createServer } from 'node:http';
import { openProjectStore } from './store.js';
import { notFoundPage, projectPage, projectsPage } from './views.js';

const port = Number(process.env.PORT ?? 8080);
const store = openProjectStore(process.env.DB_PATH ?? './data/workboard.sqlite');

function send(response, status, body, contentType = 'text/html; charset=utf-8') {
  response.writeHead(status, { 'Content-Type': contentType });
  response.end(body);
}

async function readForm(request) {
  const chunks = [];
  let size = 0;
  for await (const chunk of request) {
    size += chunk.length;
    if (size > 64 * 1024) {
      const error = new Error('Request body is too large');
      error.status = 413;
      throw error;
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

function taskFilter(value) {
  return ['all', 'open', 'completed'].includes(value) ? value : 'all';
}

function redirect(response, location) {
  response.writeHead(303, { Location: location });
  response.end();
}

const server = createServer(async (request, response) => {
  try {
    const { pathname, searchParams } = new URL(request.url, 'http://localhost');
    if (request.method === 'GET' && pathname === '/health') {
      return send(response, 200, JSON.stringify({ status: 'ok' }), 'application/json');
    }
    if (request.method === 'GET' && pathname === '/') {
      return send(response, 200, projectsPage(store.list()));
    }
    if (request.method === 'POST' && pathname === '/projects') {
      const form = await readForm(request);
      const name = (form.get('name') ?? '').trim();
      if (!name) {
        return send(response, 422, projectsPage(store.list(), 'Project name is required'));
      }
      store.create(name);
      return redirect(response, '/');
    }
    const projectRoute = /^\/projects\/([1-9]\d*)(?:\/tasks(?:\/([1-9]\d*)\/completion)?)?$/.exec(pathname);
    if (projectRoute) {
      const id = Number(projectRoute[1]);
      const project = Number.isSafeInteger(id) ? store.find(id) : undefined;
      if (!project) return send(response, 404, notFoundPage());
      const projectPath = `/projects/${id}`;
      if (request.method === 'GET' && pathname === projectPath) {
        const filter = taskFilter(searchParams.get('filter'));
        return send(response, 200, projectPage(project, store.listTasks(id, filter), filter));
      }
      if (request.method === 'POST' && pathname !== projectPath) {
        const form = await readForm(request);
        const filter = taskFilter(form.get('filter'));
        if (projectRoute[2]) {
          const taskId = Number(projectRoute[2]);
          if (!Number.isSafeInteger(taskId) || !store.setTaskCompleted(id, taskId, form.has('completed'))) {
            return send(response, 404, notFoundPage());
          }
        } else {
          const title = (form.get('title') ?? '').trim();
          if (!title) {
            return send(response, 422, projectPage(project, store.listTasks(id, filter), filter, 'Task title is required'));
          }
          store.createTask(id, title);
        }
        return redirect(response, `${projectPath}?filter=${filter}`);
      }
    }
    send(response, 404, notFoundPage());
  } catch (error) {
    if (error.status === 413) return send(response, 413, error.message, 'text/plain; charset=utf-8');
    console.error(error);
    send(response, 500, 'Internal server error', 'text/plain; charset=utf-8');
  }
});

server.listen(port, '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

function shutdown() {
  server.close(() => {
    store.close();
  });
}

process.once('SIGTERM', shutdown);
process.once('SIGINT', shutdown);
function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

